"use client"

import React, { createContext, useContext, useState, useCallback, useMemo } from "react"

export interface Tab {
  id: string
  title: string
  content: React.ReactNode
  closable?: boolean
}

interface MdiContextType {
  tabs: Tab[]
  activeTabId: string | null
  openTab: (id: string, title: string, content: React.ReactNode, closable?: boolean) => void
  closeTab: (id: string) => void
  setActiveTabId: (id: string) => void
}

const MdiContext = createContext<MdiContextType | undefined>(undefined)

export function MdiProvider({ children }: { children: React.ReactNode }) {
  const [tabs, setTabs] = useState<Tab[]>([])
  const [activeTabId, setActiveTabId] = useState<string | null>(null)

  const openTab = useCallback((id: string, title: string, content: React.ReactNode, closable = true) => {
    setTabs((prevTabs) => {
      const existingTab = prevTabs.find((tab) => tab.id === id)
      if (existingTab) {
        setActiveTabId(id)
        return prevTabs
      }
      const newTabs = [...prevTabs, { id, title, content, closable }]
      setActiveTabId(id)
      return newTabs
    })
  }, [])

  const closeTab = useCallback((id: string) => {
    setTabs((prevTabs) => {
      const tabIndex = prevTabs.findIndex((tab) => tab.id === id)
      if (tabIndex === -1) return prevTabs

      const newTabs = prevTabs.filter((tab) => tab.id !== id)
      
      if (activeTabId === id) {
        if (newTabs.length > 0) {
          const nextIndex = Math.max(0, tabIndex - 1)
          setActiveTabId(newTabs[nextIndex].id)
        } else {
          setActiveTabId(null)
        }
      }
      
      return newTabs
    })
  }, [activeTabId])

  const value = useMemo(() => ({
    tabs,
    activeTabId,
    openTab,
    closeTab,
    setActiveTabId
  }), [tabs, activeTabId, openTab, closeTab])

  return (
    <MdiContext.Provider value={value}>
      {children}
    </MdiContext.Provider>
  )
}

export function useMdi() {
  const context = useContext(MdiContext)
  if (context === undefined) {
    throw new Error("useMdi must be used within an MdiProvider")
  }
  return context
}
